for code, pid, name, level, language, field, campus, degree_class, mode in PROFILES:
    duration, ects = (3, 180) if level == "BSc" else (2, 120)
    SOURCES.append(source(f"SRC-UNIGE-{code}-PROFILE-2026", f"{name} {level} – course profile 2026/27", f"https://corsi.unige.it/en/corsi/{code}", f"The official profile displays 2026/2027: {name}, {level}, {duration} years/{ects} ECTS, class {degree_class}, {language}, {campus}, {mode}. It describes free access subject to the course's entry/initial or personal preparation checks. This verifies the previous-cycle listing only.", ["program.previous_cycle_course_listing"], kind="Official degree profile"))
    SOURCES.append(source(f"SRC-UNIGE-{code}-ADMISSION", f"{name} {level} – admission criteria", f"https://corsi.unige.it/en/corsi/{code}/prospective-students-admission-criteria-procedure", "; ".join(f"{k}: {v}" for k, v in REQUIREMENTS[code].items()) + ". Reviewed alongside the 2026/27 profile; no 2027/28 course call is established.", ["program.previous_cycle_requirements"], cycle="general", kind="Official course admissions guidance"))


