def apply(universities, programs, fact):
    uni = next(u for u in universities if u["id"] == "genova")
    uni.update(application_portal_url=PORTAL, contact_email="sass@unige.it",
               contact_url="https://unige.it/en/welcoming-international-students",
               last_checked=CHECKED, research_summary=REPORT)
    for key in uni["coverage"]:
        if key != "official_website_visited":
            uni["coverage"][key] = "partial"
    uni["cycle_facts"] = {
        "application_windows": fact([{"label":"Visa preselection (expected)", "expected_opening":"Mid-December 2026", "expected_closure":"End of March 2027", "eligible_group":"Visa applicants with non-Italian qualifications", "exact_dates":False}], "REQUIRES_VERIFICATION", ["SRC-UNIGE-2027"], "The official 2027/28 notice gives approximate months only; exact opening and closing dates remain unpublished."),
        "application_fee": fact({"amount_eur":30,"maximum_assessment_applications":2,"scope":"2027/28 UniGeApply visa-applicant preselection"}, "CONFIRMED", ["SRC-UNIGE-2027"]),
        "tuition_2027_2028": fact(None,"REQUIRES_VERIFICATION",["SRC-UNIGE-FEES-2026"],"No 2027/28 tuition schedule was identified. €136 is the previous cycle's initial fixed payment, not the annual cost."),
        "scholarships_2027_2028": fact(None,"REQUIRES_VERIFICATION",["SRC-ALISEO-CALL-2026","SRC-ALISEO-DATES-2026"],"The reviewed regional scholarship call covers 2026/27. No 2027/28 call, thresholds or award values were identified."),
        "previous_cycle_application_windows": fact({"academic_year":"2026/27","visa_preselection":{"start":"2025-11-26","end":"2026-03-20","Computer_Engineering_BSc_early_closure":"2026-03-08"},"resident_selection":{"start":"2026-04-09","MSc_end":"2026-08-28","BSc_end":"2026-09-25"},"exceptions":"Restricted courses follow dedicated calls"},"CONFIRMED",["SRC-UNIGE-APPLY-2026"],"These closed 2026/27 assessment windows are historical context only."),
        "previous_cycle_international_process": fact({"academic_year":"2026/27","foreign_qualification_assessment":"UniGeApply","visa_pre_enrolment":"Universitaly after successful assessment","visa_applicant_fee_eur":30,"maximum_assessment_requests":2,"resident_spring_assessment":"Free","course_assessment":"Separate course requirements and readiness checks apply"},"CONFIRMED",["SRC-UNIGE-APPLY-2026"],"Prior-cycle qualification and visa route only; recheck 2027/28 documentation and course procedures."),
        "previous_cycle_tuition": fact({"academic_year":"2026/27","first_installment_eur":136,"stamp_duty_eur":16,"minimum_regional_tax_eur":120,"variable_university_contribution_eur_range":[0,3300],"conditions":"ISEE-U or eligible equivalent ISEE, fee class, course group, full/part-time enrollment and exemptions","installments":3,"second_installment_deadline":"2026-12-10","third_installment_deadline":"2027-06-23"},"CONFIRMED",["SRC-UNIGE-FEES-2026","SRC-UNIGE-ISEE-2026"],"University-wide 2026/27 framework. €136 is the first installment, not total tuition; the contribution range excludes stamp and regional tax and depends on eligibility."),
        "previous_cycle_scholarships": fact({"academic_year":"2026/27","ALiSEO":{"application_window":"15 June–31 July 2026, 12:00","ISEE_or_ISEEUP_ceiling_eur":28339,"ISPEU_or_ISPEUP_ceiling_eur":61608,"eligibility":"Enrollment, economic and merit requirements in the annual call","benefits":"Income/status-dependent cash, meal and possible housing; the gross amount includes service values","foreign_income":"Equivalent-ISEE documentation under the call"},"university_fee_reductions":{"first_year_highest_entry_qualification_mark_eur":200,"later_year_merit_brackets_eur":[400,200]}},"CONFIRMED",["SRC-ALISEO-CALL-2026","SRC-ALISEO-DATES-2026","SRC-UNIGE-BENEFITS"],"Closed prior-cycle regional competition and current fee-reduction guidance only; awards are conditional, not guaranteed or confirmed for 2027/28."),
    }
    for code, pid, name, level, language, field, campus, degree_class, mode in PROFILES:
        p = next(p for p in programs if p["id"] == pid)
        profile_sid, admission_sid = f"SRC-UNIGE-{code}-PROFILE-2026", f"SRC-UNIGE-{code}-ADMISSION"
        p.update(program=name, city=campus, overall_status="REQUIRES_VERIFICATION", last_checked=CHECKED)
        for key, value in (("level",level),("language",language),("field",field)):
            p[key] = fact(value,"REQUIRES_VERIFICATION",[profile_sid],"Official 2026/27 course profile only; confirm the 2027/28 course offer.")
        p["availability_2027_2028"] = fact(None,"REQUIRES_VERIFICATION",[profile_sid,"SRC-UNIGE-2027"],"The course profile is for 2026/27. The university-wide 2027/28 visa preselection notice does not name a new first-year offer for this course; no discontinuation is inferred.")
        p["previous_cycle_tags"] = dict(level=level,language=language,field=field,cycle="2026-2027",label="Official 2026/27 course evidence only; 2027/28 first-year intake remains unverified")
        extras = {"11965":["SRC-UNIGE-CE-MSC-ASSESSMENT"],"11896":["SRC-UNIGE-CS-BSC-ASSESSMENT"],"12133":["SRC-UNIGE-CE-BSC-ASSESSMENT-2026"]}.get(code,[])
        p["source_ids"] = [profile_sid,admission_sid,"SRC-UNIGE-CATALOGUE-2026","SRC-UNIGE-2027","SRC-UNIGE-APPLY-2026","SRC-UNIGE-FEES-2026","SRC-UNIGE-ISEE-2026","SRC-UNIGE-BENEFITS","SRC-ALISEO-CALL-2026","SRC-ALISEO-DATES-2026","SRC-UNIGE-CONTACT"] + extras
        p["facts"] = {
            "previous_cycle_course_listing": fact({"academic_year":"2026/27","official_name":name,"course_code":code,"level":level,"language":language,"duration_years":3 if level=="BSc" else 2,"ects":180 if level=="BSc" else 120,"degree_class":degree_class,"campus":campus,"teaching_mode":mode,"access":"Free access subject to course checks"},"CONFIRMED",[profile_sid],"Named 2026/27 course listing only; English web translation is not evidence of English teaching."),
            "previous_cycle_program_requirements": fact(REQUIREMENTS[code],"CONFIRMED",[admission_sid]+extras,"Course guidance reviewed alongside the 2026/27 profile; the undated admission page does not confirm the next cycle's criteria. Computer Science MSc's certificate clauses specifically retain older-year labels."),
            "previous_cycle_international_admission": uni["cycle_facts"]["previous_cycle_international_process"],
            "previous_cycle_tuition": uni["cycle_facts"]["previous_cycle_tuition"],
            "previous_cycle_scholarships": uni["cycle_facts"]["previous_cycle_scholarships"],
            "application_windows": fact(None,"REQUIRES_VERIFICATION",["SRC-UNIGE-2027",admission_sid],"No exact program-specific 2027/28 application window was identified. University-level visa preselection is expected from mid-December 2026 to end-March 2027; wait for exact dates and the course procedure."),
            "application_fee_2027_2028": uni["cycle_facts"]["application_fee"],
            "program_specific_requirements_2027_2028": fact(None,"REQUIRES_VERIFICATION",[admission_sid,"SRC-UNIGE-2027"],"No 2027/28 course-specific requirements or places were identified."),
            "tuition_2027_2028": uni["cycle_facts"]["tuition_2027_2028"],
            "scholarships_2027_2028": uni["cycle_facts"]["scholarships_2027_2028"],
            "acceptance_rate": fact(None,"UNAVAILABLE",[profile_sid,admission_sid],"No comparable applicant and admitted totals for this course and intake were identified; no acceptance rate is calculated."),
        }
        if code == "12133":
            p["facts"]["previous_cycle_assessment_dates"] = fact({"academic_year":"2026/27","test":"ATHENA at Imperia","dates":["2026-09-18","2026-10-09","2026-10-30","2026-12-04","2027-01-22"],"rescheduled":"20 November 2026 moved to 4 December 2026","January_eligibility":"Non-EU students arriving from December onward"},"CONFIRMED",extras,"Historical 2026/27 assessment dates only; these are not 2027/28 selection windows.")
    cores = next(p for p in programs if p["id"] == "discovered-022")
    cores["source_ids"] = ["SRC-UNIGE-CORES-2027"]
